class Solution:
    def countVowelSubstrings(self, word: str) -> int:
        vowels = "aeiou"
        n = len(word)
        ans = 0
        for i in range(n):
            if word[i] not in vowels:
                continue
            mask = 0
            for j in range(i, n):
                p = vowels.find(word[j])
                if p == -1:
                    break
                mask |= 1 << p
                if mask == 31:
                    ans += 1
        return ans

