        int n = word.size(), ans = 0;
        for (int i = 0; i < n; i++) {
            if (vowels.find(word[i]) == string::npos) continue;
            int mask = 0;
            for (int j = i; j < n; j++) {
                int p = vowels.find(word[j]);
                if (p == string::npos) break;
                mask |= 1 << p;
                if (mask == 31) ans++;
            }
        }
        return ans;
    }
};

