class Solution {
public:
    int countVowelSubstrings(string word) {
        auto isVowel = [](char c) {
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        };
        auto atMost = [&](int k) {
            vector<int> cnt(26, 0);
            int distinct = 0, left = 0;
            long long res = 0;
            for (int right = 0; right < (int)word.size(); right++) {
                if (!isVowel(word[right])) {
                    fill(cnt.begin(), cnt.end(), 0);
                    distinct = 0;
                    left = right + 1;
                    continue;
                }
                if (cnt[word[right] - 'a']++ == 0) distinct++;
                while (distinct > k) {
                    if (--cnt[word[left] - 'a'] == 0) distinct--;
                    left++;
                }
                res += right - left + 1;
            }
            return (int)res;
        };
        return atMost(5) - atMost(4);
    }
};

